// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * SPIKE (Routine C, no production changes): reproduces the reported class-join COUNT shape
 *
 * <pre>
 * SELECT (count(*) AS ?count) WHERE {
 *   ?s a bb:TrademarkApplication . ?s bb:hasCaseFileOwner ?o . ?o a bb:TrademarkCaseFileOwner }
 * </pre>
 *
 * and compares the strategy the adaptive cost model dispatches against the alternatives it declined as
 * "adaptive-higher-cost".
 */
class ScratchTrademarkCountTimingTest {

	private static final String BB = "http://bloomberg#";

	/** Reported store: 11.7M applications, 28.5M hasCaseFileOwner edges (~2.4/app). Scaled by scratch.scale. */
	private static final int APPS = Integer.getInteger("scratch.apps", 3_000_000);
	private static final int OWNERS = Integer.getInteger("scratch.owners", 1_000_000);
	private static final int EDGES_PER_APP = Integer.getInteger("scratch.edgesPerApp", 2);
	/** Percent of owners actually typed bb:TrademarkCaseFileOwner. */
	private static final int OWNER_TYPED_PCT = Integer.getInteger("scratch.ownerTypedPct", 90);
	private static final int REPEATS = Integer.getInteger("scratch.repeats", 5);

	private static final String QUERY = "PREFIX bb: <" + BB + "> SELECT (count(*) as ?count) WHERE { "
			+ "?s a bb:TrademarkApplication. ?s bb:hasCaseFileOwner ?o . ?o a bb:TrademarkCaseFileOwner }";

	private static final String[] TOGGLES = {
			"rdf4j.lmdb.costCalibration.enabled",
			"rdf4j.lmdb.costCalibration.record",
			"rdf4j.lmdb.packedFtree.enabled",
			"rdf4j.lmdb.parallel.enabled",
	};

	@Test
	void timeTheStrategies(@TempDir File dir) throws Exception {
		List<String[]> saved = new ArrayList<>();
		for (String key : TOGGLES) {
			saved.add(new String[] { key, System.getProperty(key) });
		}
		LmdbStoreConfig loadConfig = new LmdbStoreConfig("spoc,posc,ospc");
		loadConfig.setDirectAdjacencyMode(DirectAdjacencyMode.DISABLED);
		SailRepository loader = new SailRepository(new LmdbStore(dir, loadConfig));
		loader.init();
		try {
			load(loader);
		} finally {
			loader.shutDown();
		}

		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc");
		config.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER);
		config.setDirectAdjacencyBuildOnStart(true);
		config.setDirectAdjacencyMaxBytes(8L * 1024 * 1024 * 1024);
		LmdbStore store = new LmdbStore(dir, config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			System.out.println("[scratch] adjacency ready: "
					+ store.awaitDirectAdjacencyReady(900, TimeUnit.SECONDS));
			System.out.println("[scratch] apps=" + APPS + " owners=" + OWNERS + " edgesPerApp=" + EDGES_PER_APP
					+ " edges=" + ((long) APPS * EDGES_PER_APP));

			// Sequential-scan baselines: what one linear pass over each input costs on this store.
			runQuery(repository, "BASELINE scan type extent",
					"PREFIX bb: <" + BB + "> SELECT (count(*) as ?count) WHERE { ?s a bb:TrademarkApplication }");
			runQuery(repository, "BASELINE scan edge predicate",
					"PREFIX bb: <" + BB + "> SELECT (count(*) as ?count) WHERE { ?s bb:hasCaseFileOwner ?o }");
			runProfiled(repository, "BASELINE two-pattern join (no owner type)",
					"PREFIX bb: <" + BB + "> SELECT (count(*) as ?count) WHERE { "
							+ "?s a bb:TrademarkApplication. ?s bb:hasCaseFileOwner ?o }");

			// (a) exactly as shipped: learned adaptive dispatch decides
			run(repository, "adaptive=on (as shipped)");

			// (b) learned dispatch off: the static cost + preference ladder decides
			System.setProperty("rdf4j.lmdb.costCalibration.enabled", "false");
			run(repository, "adaptive=off (static cost + preference ladder)");

			// (c) packedFtreeAggregate removed: what the reported plan actually dispatched
			System.setProperty("rdf4j.lmdb.packedFtree.enabled", "false");
			run(repository, "packedFtree=off");

			// (d) kernels off too: leaves parallelAggregation / factorizedTail / nestedLoop
			System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "false");
			System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "false");
			run(repository, "packedFtree=off kernels=off");

			// (e) and without parallelism, to isolate the plain nested loop the report dispatched
			System.setProperty("rdf4j.lmdb.parallel.enabled", "false");
			run(repository, "packedFtree=off kernels=off parallel=off (nestedLoop)");
			System.clearProperty("rdf4j.lmdb.parallel.enabled");
			System.clearProperty("rdf4j.lmdb.janinoCodegen.enabled");
			System.clearProperty("rdf4j.lmdb.kernelInterpreter.enabled");
			System.clearProperty("rdf4j.lmdb.packedFtree.enabled");
			System.clearProperty("rdf4j.lmdb.costCalibration.enabled");
		} finally {
			try {
				repository.shutDown();
			} finally {
				for (String[] entry : saved) {
					if (entry[1] == null) {
						System.clearProperty(entry[0]);
					} else {
						System.setProperty(entry[0], entry[1]);
					}
				}
			}
		}
	}

	private void runQuery(SailRepository repository, String label, String query) {
		long best = Long.MAX_VALUE;
		String value = "?";
		for (int i = 0; i < REPEATS; i++) {
			long start = System.nanoTime();
			try (SailRepositoryConnection connection = repository.getConnection();
					TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					value = result.next().getValue("count").stringValue();
				}
			}
			best = Math.min(best, System.nanoTime() - start);
		}
		System.out.println("[scratch] === " + label + " best=" + TimeUnit.NANOSECONDS.toMillis(best) + " ms count="
				+ value);
	}

	private void run(SailRepository repository, String label) {
		runProfiled(repository, label, QUERY);
	}

	private void runProfiled(SailRepository repository, String label, String q) {
		long best = Long.MAX_VALUE;
		String value = "?";
		java.util.Map<String, Integer> leaves = new java.util.concurrent.ConcurrentHashMap<>();
		java.util.Map<String, Integer> paths = new java.util.concurrent.ConcurrentHashMap<>();
		java.util.concurrent.atomic.AtomicBoolean stop = new java.util.concurrent.atomic.AtomicBoolean();
		ScratchProfilers.startSampler(Thread.currentThread(), leaves, paths, stop);
		for (int i = 0; i < REPEATS; i++) {
			long start = System.nanoTime();
			try (SailRepositoryConnection connection = repository.getConnection();
					TupleQueryResult result = connection.prepareTupleQuery(q).evaluate()) {
				while (result.hasNext()) {
					value = result.next().getValue("count").stringValue();
				}
			}
			long elapsed = System.nanoTime() - start;
			best = Math.min(best, elapsed);
			System.out.println("[scratch] " + label + " run " + i + " = "
					+ TimeUnit.NANOSECONDS.toMillis(elapsed) + " ms (count=" + value + ")");
		}
		stop.set(true);
		System.out.println("[scratch] === " + label + " best=" + TimeUnit.NANOSECONDS.toMillis(best) + " ms count="
				+ value);
		ScratchProfilers.report("LEAF -- " + label, leaves, 14);
		ScratchProfilers.report("PATH -- " + label, paths, 3);
		System.out.println("[scratch-plan] >>>>>>>>>> " + label);
		System.out.println(plan(repository, q));
		System.out.println("[scratch-plan] <<<<<<<<<< " + label);
	}

	private String plan(SailRepository repository, String q) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery(q);
			Explanation explanation = query.explain(Explanation.Level.Telemetry);
			return explanation.toString();
		}
	}

	private void load(SailRepository repository) {
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI application = vf.createIRI(BB, "TrademarkApplication");
		IRI ownerClass = vf.createIRI(BB, "TrademarkCaseFileOwner");
		IRI hasOwner = vf.createIRI(BB, "hasCaseFileOwner");
		long start = System.nanoTime();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			long added = 0;
			for (int a = 0; a < APPS; a++) {
				IRI subject = vf.createIRI(BB, "app" + a);
				connection.add(subject, RDF.TYPE, application);
				added++;
				for (int e = 0; e < EDGES_PER_APP; e++) {
					connection.add(subject, hasOwner, vf.createIRI(BB, "owner" + ((a * 7 + e * 13) % OWNERS)));
					if (++added % 1_000_000 == 0) {
						connection.commit();
						connection.begin();
					}
				}
			}
			for (int o = 0; o < OWNERS; o++) {
				if (o % 100 < OWNER_TYPED_PCT) {
					connection.add(vf.createIRI(BB, "owner" + o), RDF.TYPE, ownerClass);
					if (++added % 1_000_000 == 0) {
						connection.commit();
						connection.begin();
					}
				}
			}
			connection.commit();
		}
		System.out.println("[scratch] load took " + TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start) + " ms");
	}
}
